<script setup>
import { postSession, sessionAnswers } from '../../lib/session-api.js';
import { useI18n } from '../../lib/i18n.js';
import { computed,ref } from 'vue';import { Head,Link } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';import { createQuestions,isCorrect,score,shouldAutoCheck } from '../../lib/study.js';
const {t}=useI18n();
const props=defineProps({collection:Object,words:{type:Array,default:()=>[]},mode:{type:String,default:'flashcards'},shared:{type:Boolean,default:false},settings:{type:Object,default:()=>({})}});
const options=ref({type:'choice',direction:'term',order:'random',count:Math.min(10,props.words.length),...props.settings});
const started=ref(false),questions=ref([]),index=ref(0),flipped=ref(false),answer=ref(''),checked=ref(false),correct=ref(false),results=ref([]),finished=ref(false),practiceRound=ref(false);
const sessionId=ref(null),busy=ref(false),saveState=ref(''),sessionError=ref(''),selfAssessed=ref(false);
const current=computed(()=>questions.value[index.value]);
const summary=computed(()=>score(results.value));
const modeLabel=computed(()=>({flashcards:t('Flashcards'),study:t('Study'),test:t('Test')}[props.mode]??t('Study')));
const base=computed(()=>props.shared?`/s/${props.collection.share_uuid}`:`/collections/${props.collection.id}`);
const wrong=computed(()=>results.value.filter(r=>!r.correct));
async function start(retry=false){
 if(busy.value||saveState.value==='error')return;
 busy.value=true;sessionError.value='';
 try {
  const ids=[...new Set(wrong.value.map(r=>r.id))];
  if(props.shared){const source=retry?props.words.filter(w=>ids.includes(w.id)):props.words;questions.value=createQuestions(source,{...options.value,count:retry?source.length:options.value.count});sessionId.value=null;}
  else {const data=await postSession(`${base.value}/sessions`,{mode:props.mode,settings:{...options.value,count:retry?ids.length:options.value.count},...(retry?{word_ids:ids}:{}),practice_round:retry});questions.value=data.questions;sessionId.value=data.id;}
  index.value=0;results.value=[];started.value=true;finished.value=false;practiceRound.value=retry;saveState.value='';reset();
 }catch(error){sessionError.value=t(error.message);}finally{busy.value=false;}
}
async function save(){
 if(props.shared||busy.value||saveState.value==='saved')return;
 busy.value=true;saveState.value='saving';sessionError.value='';
 try{const data=await postSession(`${base.value}/sessions/${sessionId.value}/complete`,{answers:sessionAnswers(results.value,props.mode)});if(data.results)results.value=data.results;saveState.value='saved';}
 catch(error){saveState.value='error';sessionError.value=t(error.message);}finally{busy.value=false;}
}
function reset(){selfAssessed.value=false;flipped.value=false;answer.value='';checked.value=false;correct.value=false;}
function check(){if(!answer.value.trim()||checked.value)return;correct.value=isCorrect(answer.value,current.value.expected);checked.value=true;if(props.mode==='test')next();}
function selectOption(value){if(checked.value)return;answer.value=value;if(shouldAutoCheck(props.mode,current.value.type))check();}
function next(mark=correct.value){if(!current.value)return;results.value.push({...current.value,answer:answer.value,correct:mark,self_assessed:selfAssessed.value});if(index.value===questions.value.length-1){finished.value=true;save();return;}index.value++;reset();}
function restart(){if(busy.value||saveState.value==='error')return;saveState.value='';started.value=false;finished.value=false;results.value=[];reset();}
</script>
<template><Head :title="`${modeLabel} · ${collection.title}`"/><AppLayout :title="modeLabel" :subtitle="collection.title" :shared="shared"><template #actions><Link :href="base" class="button secondary">{{ t("← Collection") }}</Link></template><div class="study-wrap"><p v-if="sessionError" class="notice error" role="alert">{{sessionError}}</p><section v-if="!words.length" class="panel empty"><h2>{{ t("A few words first.") }}</h2><p>{{ t("This collection is empty. Add words before starting a session.") }}</p><Link :href="base" class="button">{{ t("Back to collection") }}</Link></section><section v-else-if="!started" class="panel study-settings"><span class="step-label">{{ t("MAKE IT YOURS") }}</span><h2>{{ t("How would you like to practice?") }}</h2><p class="muted">{{mode==='flashcards'?t('Turn each card over, then decide what needs another look.'):mode==='test'?t('Answer all questions, then review your results at the end.'):t('Get feedback as you go, then revisit the words that need more practice.')}}</p><form @submit.prevent="start()"><div class="two-col"><label>{{mode==='flashcards'?t('Card front'):t('Question direction')}}<select v-model="options.direction"><option value="term">{{ t("Show definition → recall word") }}</option><option value="definition">{{ t("Show word → recall definition") }}</option></select></label><label v-if="mode!=='flashcards'">{{ t("Answer style") }}<select v-model="options.type"><option value="choice">{{ t("Multiple choice") }}</option><option value="written">{{ t("Written answer") }}</option></select></label><label>{{ t("Order") }}<select v-model="options.order"><option value="random">{{ t("Shuffled") }}</option><option value="ordered">{{ t("Collection order") }}</option></select></label><label>{{ t("Number of") }}{{mode==='flashcards'?t('cards'):t('questions')}}<input v-model.number="options.count" type="number" min="1" :max="Math.min(2000,words.length)" required/></label></div><p class="muted small" v-if="mode!=='flashcards'">{{ t("Written answers ignore letter case and extra spaces, but keep accents and punctuation. During Study, you can mark an equivalent definition correct. Tests use exact normalized matching.") }}</p><p class="muted small">{{shared?t('Guest results are not saved.'):t('Completed sessions are saved to your collection history. Incomplete sessions cannot be resumed.')}} {{shared?t('No account is required, and results are not saved to the collection owner.'):t('Leaving before completion loses this attempt.')}}</p><div class="form-actions"><button class="button" :disabled="busy">{{ t("Start") }}{{modeLabel.toLowerCase()}}{{ t("→") }}</button></div></form></section><section v-else-if="finished" class="panel results"><span class="step-label">{{practiceRound?t('ANOTHER STEP FORWARD'):t('SESSION COMPLETE')}}</span><div class="score-circle">{{summary.percent}}<small>{{ t("%") }}</small></div><h2>{{summary.percent===100?t('Look at you grow.'):t('Every attempt is progress.')}}</h2><p class="muted">{{summary.correct}}{{ t("of") }}{{summary.total}} {{mode==='flashcards'?t('cards marked known'):t('answers correct')}}{{ t(".") }}</p><div v-if="shared" class="notice"><p>{{ t("Guest results are temporary. Add this collection to your account to save future sessions.") }}</p><Link :href="`/s/${collection.share_uuid}/join`" method="post" as="button" class="button">{{ t("Add to my collections") }}</Link></div><p v-if="!shared" role="status">{{saveState==='saved'?t('Saved to your private collection history.'):saveState==='saving'?t('Saving results…'):t('Results have not been saved.')}}</p><button v-if="saveState==='error'" class="button" :disabled="busy" @click="save">{{ t("Retry saving") }}</button><div class="actions centered"><button v-if="wrong.length" :disabled="busy||saveState==='error'" class="button" @click="start(true)">{{ t("Practice") }}{{wrong.length}}{{ t("again") }}</button><button class="button secondary" :disabled="busy||saveState==='error'" @click="restart">{{ t("New session") }}</button></div><div class="review-list"><article v-for="(item,i) in results" :key="i" class="review-item"><span :class="item.correct?'result-good':'result-bad'">{{item.correct?t('✓'):t('↻')}}</span><div><strong>{{item.prompt}}</strong><p>{{item.expected}}</p><small v-if="mode!=='flashcards'&&!item.correct">{{ t("Your answer:") }}{{item.answer || t('(blank)')}}</small></div></article></div></section><template v-else-if="current"><div class="study-progress"><span>{{practiceRound?t('Practice again'):modeLabel}}</span><strong>{{index+1}}{{ t("/") }}{{questions.length}}</strong></div><div class="progress-track"><div :style="{width:`${index/questions.length*100}%`}"/></div><template v-if="mode==='flashcards'"><button class="flashcard" @click="flipped=!flipped" :aria-label="flipped?t('Show question'):t('Reveal answer')"><span class="tiny-label">{{flipped?t('THE ANSWER'):current.answerKey==='term'?t('THE DEFINITION'):t('THE WORD')}}</span><strong>{{flipped?current.expected:current.prompt}}</strong><p v-if="flipped&&!shared&&current.note" class="card-note">{{current.note}}</p><small>{{flipped?t('↶ Tap to turn back'):t('↻ Tap to reveal')}}</small></button><div class="actions centered"><button class="button secondary" :disabled="!flipped" @click="next(false)">{{ t("↻ Still learning") }}</button><button class="button" :disabled="!flipped" @click="next(true)">{{ t("✓ I know this") }}</button></div></template><section v-else class="panel question-panel"><span class="tiny-label">{{current.answerKey==='term'?t('WHICH WORD FITS?'):t('WHAT DOES THIS MEAN?')}}</span><h2>{{current.prompt}}</h2><form @submit.prevent="check"><div v-if="current.type==='choice'" class="answer-options"><label v-for="(option,i) in current.options" :key="option" :class="['answer-option',{selected:answer===option}] "><input type="radio" name="answer-choice" :checked="answer===option" :value="option" @change="selectOption(option)" :disabled="checked" required/><span class="option-letter">{{String.fromCharCode(65+i)}}</span><span>{{option}}</span></label></div><label v-else>{{ t("Your answer") }}<textarea v-model="answer" :disabled="checked" rows="3" required :placeholder="t(&quot;Make room for recall…&quot;)"/></label><p v-if="current.type==='written'&&options.type==='choice'" class="muted small">{{ t("Not enough distinct options for this card, so try a written answer.") }}</p><div v-if="checked" :class="['answer-feedback',correct?'good':'needs-practice']" role="status"><strong>{{correct?t('✓ You got it.'):t('↻ One to remember.')}}</strong><p>{{current.expected}}</p><button v-if="!correct&&current.type==='written'&&current.answerKey==='definition'" type="button" class="text-button" @click="correct=true;selfAssessed=true">{{ t("My definition means the same thing") }}</button></div><div class="form-actions"><button v-if="!checked && !shouldAutoCheck(mode,current.type)" class="button" :disabled="!answer.trim()">{{mode==='test'?t('Submit answer →'):t('Check answer')}}</button><button v-else-if="checked" class="button" type="button" @click="next()">{{index===questions.length-1?t('See results'):t('Next word →')}}</button></div></form></section></template></div></AppLayout></template>
